    @Nested
    @DisplayName("Content-Encoding lie")
    inner class ContentEncodingLie {
        @Test
        @DisplayName("Gap AL: Content-Encoding gzip on a non-gzip body surfaces ApiException")
        fun lyingGzipContentEncodingWrappedInApiException() {
            // A hostile/misconfigured server claims `Content-Encoding: gzip` but
            // sends plaintext bytes. DefaultApiClient decodes the body itself
            // after reading it, so the gzip inflater runs over the body and
            // fails. A response did arrive, so the failure is exactly
            // ApiException carrying the real status (200) -- never
            // NetworkException, and never the corrupted bytes passed through.
            val engine =
                MockEngine { _ ->
                    respond(
                        content = "this is plain text, not gzip".toByteArray(Charsets.UTF_8),
                        status = HttpStatusCode.OK,
                        headers = headersOf("Content-Encoding", "gzip"),
                    )
                }
            val apiClient = DefaultApiClient(HttpClient(engine) { followRedirects = false })
            val ex =
                assertThrowsExactly(ApiException::class.java) {
                    runBlocking {
                        apiClient.sendRequest("GET", "http://localhost/lying-gzip", emptyMap(), null)
                    }
                }
            assertEquals(200, ex.statusCode)
            // A response arrived, so the headers are kept: null would mean that none did.
            assertEquals("gzip", ex.responseHeaders?.get("content-encoding"))
            assertFalse(ex is com.example.petstore.errors.NetworkException, "a corrupt body is not a network failure")
            assertInstanceOf(java.io.IOException::class.java, ex.cause)
        }

        @Test
        @DisplayName("unsupported Content-Encoding surfaces ApiException, never the still-encoded body")
        fun unknownContentEncodingWrappedInApiException() {
            // An unrecognised Content-Encoding the client cannot decode must
            // surface a typed ApiException carrying the real status (200), never
            // a NetworkException, and never the body handed back still encoded.
            val engine =
                MockEngine { _ ->
                    respond(
                        content = "payload".toByteArray(Charsets.UTF_8),
                        status = HttpStatusCode.OK,
                        headers = headersOf("Content-Encoding", "made-up-codec"),
                    )
                }
            val apiClient = DefaultApiClient(HttpClient(engine) { followRedirects = false })
            val ex =
                assertThrowsExactly(ApiException::class.java) {
                    runBlocking {
                        apiClient.sendRequest("GET", "http://localhost/unknown-encoding", emptyMap(), null)
                    }
                }
            assertEquals(200, ex.statusCode)
            assertFalse(ex is com.example.petstore.errors.NetworkException, "an unsupported encoding is not a network failure")
            assertInstanceOf(java.io.IOException::class.java, ex.cause)
        }

        @Test
        @DisplayName("br and zstd without their codec library raise instead of returning the encoded body")
        fun missingCodecLibraryRaises() {
            for (encoding in listOf("br", "zstd")) {
                val ex =
                    assertThrows(java.io.IOException::class.java) {
                        decodeViaInputStream("payload".toByteArray(), encoding, "no.such.$encoding.InputStream")
                    }
                assertEquals(
                    "Received a $encoding-encoded response but the $encoding library is unavailable",
                    ex.message,
                )
            }
        }

        @Test
        @DisplayName("decodeContentEncoding passes identity and an empty value through and raises on any other value")
        fun decodeContentEncodingPassesOnlyIdentityThrough() {
            val body = "payload".toByteArray()
            assertArrayEquals(body, decodeContentEncoding(body, "identity"))
            assertArrayEquals(body, decodeContentEncoding(body, " "))
            val ex =
                assertThrowsExactly(java.io.IOException::class.java) {
                    decodeContentEncoding(body, "compress")
                }
            assertEquals("Unsupported Content-Encoding 'compress'", ex.message)
        }

        @Test
        @DisplayName("Gap AL: empty body declared gzip passes through as empty, never raises")
        fun emptyGzipBodyPassesThroughAsEmpty() {
            // A zero-byte body still advertising `Content-Encoding: gzip` has
            // nothing to inflate. The decompressor must return the empty body
            // unchanged -- never raise on the absent gzip stream.
            val engine =
                MockEngine { _ ->
                    respond(
                        content = ByteArray(0),
                        status = HttpStatusCode.OK,
                        headers = headersOf("Content-Encoding", "gzip"),
                    )
                }
            val apiClient = DefaultApiClient(HttpClient(engine) { followRedirects = false })
            var response: ApiHttpResponse? = null
            runBlocking {
                response = apiClient.sendRequest("GET", "http://localhost/empty-gzip", emptyMap(), null)
            }
            assertEquals(200, response!!.statusCode)
            assertEquals("", response!!.body)
        }
    }

    @Nested
    @DisplayName("Content-Encoding decoding and Accept-Encoding")
    inner class ContentEncodingDecoding {
        private fun encodedResponse(
            content: ByteArray,
            encoding: String,
        ): ApiHttpResponse {
            val engine =
                MockEngine { _ ->
                    respond(
                        content = content,
                        status = HttpStatusCode.OK,
                        headers = headersOf("Content-Encoding", encoding),
                    )
                }
            val apiClient = DefaultApiClient(HttpClient(engine) { followRedirects = false })
            return runBlocking { apiClient.sendRequest("GET", "http://localhost/encoded", emptyMap(), null) }
        }

        private fun zlib(
            text: String,
            nowrap: Boolean,
        ): ByteArray {
            val out = java.io.ByteArrayOutputStream()
            java.util.zip
                .DeflaterOutputStream(out, java.util.zip.Deflater(java.util.zip.Deflater.DEFAULT_COMPRESSION, nowrap))
                .use { it.write(text.toByteArray(Charsets.UTF_8)) }
            return out.toByteArray()
        }

        @Test
        @DisplayName("a zlib-wrapped deflate response is decoded")
        fun decompressesDeflateResponse() {
            val response = encodedResponse(zlib("{\"ok\":true}", nowrap = false), "deflate")
            assertEquals(200, response.statusCode)
            assertEquals("{\"ok\":true}", response.body)
        }

        @Test
        @DisplayName("raw headerless DEFLATE surfaces ApiException carrying the real status")
        fun rawDeflateIsRefused() {
            val engine =
                MockEngine { _ ->
                    respond(
                        content = zlib("{\"ok\":true}", nowrap = true),
                        status = HttpStatusCode.OK,
                        headers = headersOf("Content-Encoding", "deflate"),
                    )
                }
            val apiClient = DefaultApiClient(HttpClient(engine) { followRedirects = false })
            val ex =
                assertThrowsExactly(ApiException::class.java) {
                    runBlocking { apiClient.sendRequest("GET", "http://localhost/raw-deflate", emptyMap(), null) }
                }
            assertEquals(200, ex.statusCode)
            assertInstanceOf(java.io.IOException::class.java, ex.cause)
        }

        @Test
        @DisplayName("a gzip response is decoded")
        fun decompressesGzipResponse() {
            val out = java.io.ByteArrayOutputStream()
            java.util.zip
                .GZIPOutputStream(out)
                .use { it.write("{\"ok\":true}".toByteArray(Charsets.UTF_8)) }
            assertEquals("{\"ok\":true}", encodedResponse(out.toByteArray(), "gzip").body)
        }

        @Test
        @DisplayName("without a caller value the client advertises gzip and deflate first")
        fun advertisesTheSupportedEncodingsByDefault() {
            var acceptEncoding: String? = null
            val client = mockClient(requestCapture = { req -> acceptEncoding = req.headers["Accept-Encoding"] })
            runBlocking {
                DefaultApiClient(client).sendRequest("GET", "http://localhost/test", emptyMap(), null)
            }
            assertEquals(supportedEncodings(), acceptEncoding)
